package integration_test
import("os";"path/filepath";"testing";"github.com/paulharkink/another-agent-capability-toolkit/internal/config";"github.com/paulharkink/another-agent-capability-toolkit/internal/forms";"github.com/paulharkink/another-agent-capability-toolkit/internal/catalog")
func TestCapabilityPackExample(t *testing.T){root,err:=filepath.Abs(filepath.Join("..","..","examples","capability-pack"));if err!=nil{t.Fatal(err)};pack,err:=config.DiscoverPack(root,filepath.Join(root,"aact.toml"),"",t.TempDir());if err!=nil{t.Fatal(err)};if len(pack.Catalog)!=1||len(pack.Catalog[0].SkillDefinitions())!=2{t.Fatalf("%+v",pack)};p:=pack.Catalog[0];profiles,err:=config.DiscoverProfiles(pack,p.ID);if err!=nil||len(profiles)!=2{t.Fatalf("%+v %v",profiles,err)};values,err:=forms.Resolve(p.Inputs,profiles[0].Raw);if err!=nil||values["enabled"]!=false{t.Fatalf("%v %v",values,err)};items,err:=catalog.InstallationItems(p,p.Sets);if err!=nil||len(items)!=2{t.Fatalf("%v %v",items,err)};if _,err:=os.Stat(filepath.Join(root,"bootstrap.ps1"));err!=nil{t.Fatal(err)}}
